window.__PIONEER_REGISTER_TEST("TEST_HIST_SET_16", [
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. बरार (इमादशाही) व बीदर (बरीदशाही)   B. सासाराम झील मकबरा\nC. हुमायूँ एवं शेरशाह सूरी (प्रशासन व आर्थिक सुधार)   D. सर थॉमस रो (ब्रिटेन)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["सर थॉमस रो (ब्रिटेन)","हुमायूँ एवं शेरशाह सूरी (प्रशासन व आर्थिक सुधार)","सासाराम झील मकबरा","() व ()"],"correct":3,"explanation":"बरार (इमादशाही) व बीदर (बरीदशाही) (1490 ई.), हुमायूँ एवं शेरशाह सूरी (प्रशासन व आर्थिक सुधार) (1540-1545 ई.), सासाराम झील मकबरा (1545 ई.), सर थॉमस रो (ब्रिटेन) (1615 ई.)। अतः सर्वप्रथम बरार (इमादशाही) व बीदर (बरीदशाही)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. अकबर की दहसाला व्यवस्था, मनसबदारी एवं सुलह-ए-कुल   B. डोमिंगो पायस (पुर्तगाल)\nC. गुरु अमरदास (तीसरे गुरु)   D. फ्रांस्वा बर्नियर एवं टैवर्नियर\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["फ्रांस्वा बर्नियर एवं टैवर्नियर","(पुर्तगाल)","अकबर की दहसाला व्यवस्था, मनसबदारी एवं सुलह-ए-कुल","गुरु अमरदास (तीसरे गुरु)"],"correct":1,"explanation":"डोमिंगो पायस (पुर्तगाल) (1520 ई.), गुरु अमरदास (तीसरे गुरु) (1552-1574 ई.), अकबर की दहसाला व्यवस्था, मनसबदारी एवं सुलह-ए-कुल (1580 ई.), फ्रांस्वा बर्नियर एवं टैवर्नियर (1658 ई.)। अतः सर्वप्रथम डोमिंगो पायस (पुर्तगाल)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. डोमिंगो पायस (पुर्तगाल)   B. सुहरावर्दी सिलसिला (भारत)\nC. अटाला मस्जिद (जौनपुर)   D. फिरोजशाह तुगलक की कल्याणकारी एवं कट्टर नीतियाँ\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["अटाला मस्जिद (जौनपुर)","सुहरावर्दी सिलसिला (भारत)","फिरोजशाह तुगलक की कल्याणकारी एवं कट्टर नीतियाँ","(पुर्तगाल)"],"correct":3,"explanation":"सुहरावर्दी सिलसिला (भारत) (13वीं सदी ई.), फिरोजशाह तुगलक की कल्याणकारी एवं कट्टर नीतियाँ (1351-1388 ई.), अटाला मस्जिद (जौनपुर) (1408 ई.), डोमिंगो पायस (पुर्तगाल) (1520 ई.)। अतः सबसे अंत में डोमिंगो पायस (पुर्तगाल)।"},
  {"q":"[PSC/CDS युग्म पहचान — विदेशी यात्री एवं शासक] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. अब्दुर रज्जाक (फारस/समरकंद) : शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)\n2. फ्रांस्वा बर्नियर एवं टैवर्नियर : कृष्णदेवराय (विजयनगर, ~1520 ई.)\n3. अफनासी निकितिन (रूस) : बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)\n4. डोमिंगो पायस (पुर्तगाल) : अच्युतदेवराय (विजयनगर, ~1535 ई.)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: निकितिन ने बीदर केंद्रित बहमनी सल्तनत में आम जनता की गरीबी व अमीरों की विलासिता का वर्णन किया। (अन्य सही युग्म: अब्दुर रज्जाक (फारस/समरकंद)→देवराय द्वितीय (विजयनगर, 1443 ई.), फ्रांस्वा बर्नियर एवं टैवर्नियर→शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68), डोमिंगो पायस (पुर्तगाल)→कृष्णदेवराय (विजयनगर, ~1520 ई.))।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. गयासुद्दीन बलबन ने 'तुर्कान-ए-चहलगानी' (चालीसा गुट) का गठन कर तुर्क अमीरों को असीमित प्रशासनिक शक्तियाँ प्रदान कीं।\n2. अब्दुल कादिर बदायूँनी अपनी पुस्तक 'मुन्तखब-उत-तवारीख' में अकबर की धार्मिक उदारता व 'दीन-ए-इलाही' का सबसे बड़ा प्रशंसक था।\n3. मध्यकालीन ग्रंथ एवं लेखक के अंतर्गत 'रहीम दोहावली / प्रेमवाटिका' का ऐतिहासिक संबंध 'मोतमिद खाँ' से था।\n4. 1565 ई. के तालीकोटा (राक्षसी-तंगड़ी या बन्नीहट्टी) युद्ध में दक्कनी सल्तनतों (बीजापुर, अहमदनगर, गोलकुंडा, बीदर) के महासंघ ने रामराय को हराकर विजयनगर की शक्ति तोड़ दी।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (1565 ई. के तालीकोटा (राक्षसी-तंगड़ी या बन्नीहट्टी) युद्ध में दक्कनी सल्तनतों (बीजापुर, अहमदनगर, गोलकुंडा, बीदर) के महासंघ ने रामराय को हराकर विजयनगर की शक्ति तोड़ दी।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. फारसी राजदूत अब्दुर रज्जाक तुगलक शासक फिरोजशाह के दरबार में दिल्ली आया था और उसने बहमनी की बजाय दिल्ली की सती प्रथा पर लिखा।\n2. मराठा अष्टप्रधान परिषद के अंतर्गत 'वाकियानवीस (मंत्री)' का ऐतिहासिक संबंध 'मुख्य सैन्य कमांडर (पैदल व घुड़सवार नेतृत्व)' से था।\n3. सल्तनत विभाग एवं सुल्तान के अंतर्गत 'दीवान-ए-बंदगान' का ऐतिहासिक संबंध 'वित्त एवं राजस्व मंत्रालय (प्रमुख: वजीर)' से था।\n4. डोमिंगो पायस ने तुलुव वंश के कृष्णदेवराय के व्यक्तित्व व महानवमी उत्सव का सुंदर चित्रण किया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (डोमिंगो पायस ने तुलुव वंश के कृष्णदेवराय के व्यक्तित्व व महानवमी उत्सव का सुंदर चित्रण किया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. उत्तर-मुगल शासक, सैय्यद बंधु एवं नादिर शाह का आक्रमण   B. बरार (इमादशाही) व बीदर (बरीदशाही)\nC. गुरु अमरदास (तीसरे गुरु)   D. बाबर की भारत विजय व चार प्रमुख युद्ध (1526–1529)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["() व ()","बाबर की भारत विजय व चार प्रमुख युद्ध (1526–1529)","उत्तर-मुगल शासक, सैय्यद बंधु एवं नादिर शाह का आक्रमण","गुरु अमरदास (तीसरे गुरु)"],"correct":0,"explanation":"बरार (इमादशाही) व बीदर (बरीदशाही) (1490 ई.), बाबर की भारत विजय व चार प्रमुख युद्ध (1526–1529) (1526 ई.), गुरु अमरदास (तीसरे गुरु) (1552-1574 ई.), उत्तर-मुगल शासक, सैय्यद बंधु एवं नादिर शाह का आक्रमण (1739 ई.)। अतः सर्वप्रथम बरार (इमादशाही) व बीदर (बरीदशाही)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: दक्कनी सल्तनत व राजवंश के अंतर्गत 'अहमदनगर (निजामशाही, 1490)' का ऐतिहासिक संबंध 'फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद' से था।\nकथन-2: अल-बरूनी ने 11वीं सदी में भारत की विद्या, धर्म, विज्ञान व समाज पर 'किताब-उल-हिन्द' लिखी।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('अहमदनगर (निजामशाही, 1490)' का सही संबंध 'मलिक अहमद' से था — मलिक अहमद ने 1490 में अहमदनगर की स्थापना की; यहीं वजीर मलिक अंबर ने छापामार युद्ध व राजस्व सुधार किए।)। कथन-2 सत्य है (अल-बरूनी ने 11वीं सदी में भारत की विद्या, धर्म, विज्ञान व समाज पर 'किताब-उल-हिन्द' लिखी।)।"},
  {"q":"[UPSC Prelims पैटर्न — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. निकोलो कोंटी (इटली) : कृष्णदेवराय (विजयनगर, ~1520 ई.)\n2. डोमिंगो पायस (पुर्तगाल) : अच्युतदेवराय (विजयनगर, ~1535 ई.)\n3. फर्नओ नूनिज (पुर्तगाल) : शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: निकोलो कोंटी (इटली) — देवराय प्रथम (विजयनगर, 1420 ई.))। युग्म 2 गलत (सही: डोमिंगो पायस (पुर्तगाल) — कृष्णदेवराय (विजयनगर, ~1520 ई.))। युग्म 3 गलत (सही: फर्नओ नूनिज (पुर्तगाल) — अच्युतदेवराय (विजयनगर, ~1535 ई.))।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. फर्नओ नूनिज (पुर्तगाल) : देवराय द्वितीय (विजयनगर, 1443 ई.)\n2. सर थॉमस रो (ब्रिटेन) : जहाँगीर (1615-1619 ई.)\n3. अफनासी निकितिन (रूस) : बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)\n4. इब्नबतूता (मोरक्को) : मुहम्मद बिन तुगलक (1333 ई.)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'फर्नओ नूनिज (पुर्तगाल)' का सही संबंध 'अच्युतदेवराय (विजयनगर, ~1535 ई.)' से है (न कि 'देवराय द्वितीय (विजयनगर, 1443 ई.)' से)। नूनिज ने अच्युतदेवराय के समय 3 वर्ष विजयनगर में रहकर महिलाओं के प्रशासनिक-सैन्य योगदान पर लिखा।"},
  {"q":"ऐतिहासिक संदर्भ में 'शिस्त (भू-राजस्व 1/6 सामान्य दर); 'अठवणे' (भू-राजस्व विभाग); 'कुडी' (कृषि श्रमिक जो भूमि बिक्री के साथ हस्तांतरित होते थे); सती प्रथा व 'बेश-वग' (मनुष्य क्रय-विक्रय)' (आर्थिक व सामाजिक तथ्य) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["अमर-नायक प्रणाली व विजयनगर आए विदेशी यात्री","कृष्णदेवराय (तुलुव वंश) एवं अष्टदिग्गज","विजयनगर की  कर, मुद्रा एवं स्थानीय परंपराएँ","विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम"],"correct":2,"explanation":"पुर्तगाली यात्री डोमिंगो पायस ने कृष्णदेवराय की 'नागलपुर' नगरी व महानवमी डिब्बा (दशहरा उत्सव) की तुलना रोम शहर की भव्यता से की है।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. अब्दुर रज्जाक (फारस/समरकंद)   B. गुरु रामदास (चौथे गुरु)\nC. सासाराम झील मकबरा   D. बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["सासाराम झील मकबरा","साम्राज्य, एवं","अब्दुर रज्जाक (फारस/समरकंद)","गुरु रामदास (चौथे गुरु)"],"correct":1,"explanation":"बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें (1347 ई.), अब्दुर रज्जाक (फारस/समरकंद) (1443 ई.), सासाराम झील मकबरा (1545 ई.), गुरु रामदास (चौथे गुरु) (1577 ई.)। अतः सर्वप्रथम बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें   B. गुरु हरगोबिंद (छठे गुरु)\nC. औरंगजेब (आलमगीर): नीतियाँ, दक्कन अभियान व विद्रोह   D. किताब-ए-नवरस\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["किताब-ए-नवरस","गुरु हरगोबिंद (छठे गुरु)","साम्राज्य, एवं","औरंगजेब (आलमगीर): नीतियाँ, दक्कन अभियान व विद्रोह"],"correct":2,"explanation":"बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें (1347 ई.), किताब-ए-नवरस (1600 ई.), गुरु हरगोबिंद (छठे गुरु) (1606-1644 ई.), औरंगजेब (आलमगीर): नीतियाँ, दक्कन अभियान व विद्रोह (1658-1707 ई.)। अतः सर्वप्रथम बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें।"},
  {"q":"[UPSC Prelims PYQ] विजयनगर साम्राज्य के शासक कृष्णदेवराय की कराधान व्यवस्था से संबंधित निम्नलिखित कथनों पर विचार कीजिए:\n1. भूमि की गुणवत्ता के आधार पर भू-राजस्व की दर नियत होती थी।\n2. कारखानों के निजी स्वामी एक औद्योगिक कर देते थे।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["1 और 2 दोनों","न तो 1, न ही 2","केवल 1","केवल 2"],"correct":0,"explanation":"विजयनगर में भूमि की उर्वरता, सिंचाई सुविधा व फसल प्रकार के अनुसार कर तय होता था ('शिस्त'), तथा व्यवसायियों, कारखानों व संपत्ति पर भी कर (उद्योग कर आदि) देय था (UPSC CSE 2016)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. आलू, तंबाकू और मक्का ऋग्वैदिक काल से ही भारत की प्राचीनतम मुख्य फसलें थीं जिनका वर्णन चरक संहिता में विस्तार से है।\n2. औरंगजेब ने हिंदू अधिकारियों की संख्या शून्य कर दी और बीजापुर व गोलकुंडा से मित्रता कर दक्कन में स्थायी शांति कायम रखी।\n3. विदेशी यात्री एवं शासक के अंतर्गत 'सर थॉमस रो (ब्रिटेन)' का ऐतिहासिक संबंध 'शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)' से था।\n4. नूनिज ने अच्युतदेवराय के समय 3 वर्ष विजयनगर में रहकर महिलाओं के प्रशासनिक-सैन्य योगदान पर लिखा।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (नूनिज ने अच्युतदेवराय के समय 3 वर्ष विजयनगर में रहकर महिलाओं के प्रशासनिक-सैन्य योगदान पर लिखा।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. मध्यकालीन ग्रंथ एवं लेखक के अंतर्गत 'हुमायूँनामा' का ऐतिहासिक संबंध 'मलिक मुहम्मद जायसी' से था।\n2. मराठा संधियाँ एवं वर्ष के अंतर्गत 'पुरंदर की संधि (1665 ई.)' का ऐतिहासिक संबंध 'पेशवा को मराठा संघ का वास्तविक सर्वोच्च प्रमुख बना दिया गया' से था।\n3. सल्तनत विभाग एवं सुल्तान के अंतर्गत 'दीवान-ए-विजारत' का ऐतिहासिक संबंध 'सैन्य विभाग (स्थापना: बलबन)' से था।\n4. विजयनगर साम्राज्य में 'अठवणे' (Athavane) केंद्रीय राजस्व विभाग था तथा कृष्णदेवराय ने विवाह कर समाप्त करके सामाजिक राहत दी (किंतु अन्य कर वेश्यालय व व्यापार आदि पर लागू थे)।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (विजयनगर साम्राज्य में 'अठवणे' (Athavane) केंद्रीय राजस्व विभाग था तथा कृष्णदेवराय ने विवाह कर समाप्त करके सामाजिक राहत दी (किंतु अन्य कर वेश्यालय व व्यापार आदि पर लागू थे)।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[PSC/CDS युग्म पहचान — विदेशी यात्री एवं शासक] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. इब्नबतूता (मोरक्को) : अच्युतदेवराय (विजयनगर, ~1535 ई.)\n2. फर्नओ नूनिज (पुर्तगाल) : बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)\n3. अफनासी निकितिन (रूस) : जहाँगीर (1615-1619 ई.)\n4. अब्दुर रज्जाक (फारस/समरकंद) : देवराय द्वितीय (विजयनगर, 1443 ई.)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: शाहरुख के राजदूत अब्दुर रज्जाक ने देवराय II के समय हम्पी की अभेद्य सात दीवारों का वर्णन किया। (अन्य सही युग्म: इब्नबतूता (मोरक्को)→मुहम्मद बिन तुगलक (1333 ई.), फर्नओ नूनिज (पुर्तगाल)→अच्युतदेवराय (विजयनगर, ~1535 ई.), अफनासी निकितिन (रूस)→बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.))।"},
  {"q":"अहमदनगर में 'निजामशाही' राजवंश की स्थापना किसने की थी?","options":["कुली कुतुब शाह","मलिक अहमद","युसुफ आदिल शाह","फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद"],"correct":1,"explanation":"मलिक अहमद ने 1490 में अहमदनगर की स्थापना की; यहीं वजीर मलिक अंबर ने छापामार युद्ध व राजस्व सुधार किए। 1633 में शाहजहाँ ने अहमदनगर को मुगल साम्राज्य में मिलाया।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. सिख गुरु परंपरा के अंतर्गत 'गुरु अंगद देव (दूसरे गुरु)' का ऐतिहासिक संबंध '22 गद्दियाँ (मंजी प्रथा) व 'आनंद कारज' विवाह गीत रचना' से था।\n2. शाहरुख के राजदूत अब्दुर रज्जाक ने देवराय II के समय हम्पी की अभेद्य सात दीवारों का वर्णन किया।\n3. भक्ति मत एवं प्रवर्तक के अंतर्गत 'विशिष्टाद्वैतवाद' का ऐतिहासिक संबंध 'माध्वाचार्य (13वीं सदी, उडुपी)' से था।\n4. मध्यकालीन स्थापत्य एवं निर्माता के अंतर्गत 'गयासुद्दीन तुगलक मकबरा' का ऐतिहासिक संबंध 'भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)' से था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (शाहरुख के राजदूत अब्दुर रज्जाक ने देवराय II के समय हम्पी की अभेद्य सात दीवारों का वर्णन किया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: विदेशी यात्री एवं शासक के अंतर्गत 'निकोलो कोंटी (इटली)' का ऐतिहासिक संबंध 'देवराय द्वितीय (विजयनगर, 1443 ई.)' से था।\nकथन-2: बक्सर के निकट चौसा में शेर खाँ ने हुमायूँ को हराया; निजाम भिश्ती ने हुमायूँ की जान बचाई।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('निकोलो कोंटी (इटली)' का सही संबंध 'देवराय प्रथम (विजयनगर, 1420 ई.)' से था — निकोलो कोंटी ने देवराय प्रथम के समय विजयनगर की यात्रा कर उत्सवों व सती प्रथा का वर्णन किया।)। कथन-2 सत्य है (बक्सर के निकट चौसा में शेर खाँ ने हुमायूँ को हराया; निजाम भिश्ती ने हुमायूँ की जान बचाई।)।"},
  {"q":"[UPSC Prelims पैटर्न — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. अफनासी निकितिन (रूस) : बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)\n2. फर्नओ नूनिज (पुर्तगाल) : अच्युतदेवराय (विजयनगर, ~1535 ई.)\n3. डोमिंगो पायस (पुर्तगाल) : देवराय प्रथम (विजयनगर, 1420 ई.)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (निकितिन ने बीदर केंद्रित बहमनी सल्तनत में आम जनता की गरीबी व अमीरों की विलासिता का वर्णन किया।) युग्म 2 सही (नूनिज ने अच्युतदेवराय के समय 3 वर्ष विजयनगर में रहकर महिलाओं के प्रशासनिक-सैन्य योगदान पर लिखा।) युग्म 3 गलत (सही: डोमिंगो पायस (पुर्तगाल) — कृष्णदेवराय (विजयनगर, ~1520 ई.))।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: दक्कनी सल्तनत व राजवंश के अंतर्गत 'गोलकुंडा (कुतुबशाही, 1512/18)' का ऐतिहासिक संबंध 'मलिक अहमद' से था।\nकथन-2: चिश्ती सिलसिले के संत सुल्तानों के शाही प्रशासन में वजीर व काजी जैसे उच्च राजनीतिक पदों पर नियुक्त रहना अपनी प्रमुख परंपरा मानते थे।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'गोलकुंडा (कुतुबशाही, 1512/18)' का सही संबंध 'कुली कुतुब शाह' से था — कुली कुतुब शाह ने गोलकुंडा राज्य की स्थापना की; बाद में मुहम्मद कुली कुतुब शाह ने चारमीनार बनवाई। (2) चिश्ती संत सत्ता, संपत्ति व राजकीय आश्रय से सदैव दूर रहते थे; निजामुद्दीन औलिया ने तो सात सुल्तानों का काल देखा पर किसी दरबार में नहीं गए।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: युसुफ आदिल शाह ने 1489 में स्वतंत्र बीजापुर राज्य बनाया जहाँ बाद में गोल गुंबज बना।\nकथन-2: वल्लभाचार्य ने बिना संन्यास लिए गृहस्थ जीवन में कृष्ण के बाल रूप की भक्ति ('पुष्टिमार्ग') का उपदेश दिया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) युसुफ आदिल शाह ने 1489 में स्वतंत्र बीजापुर राज्य बनाया जहाँ बाद में गोल गुंबज बना। (2) वल्लभाचार्य ने बिना संन्यास लिए गृहस्थ जीवन में कृष्ण के बाल रूप की भक्ति ('पुष्टिमार्ग') का उपदेश दिया।"},
  {"q":"[UPSC/PCS सूची सुमेलन — दक्कनी सल्तनत व राजवंश] सूची-I को सूची-II से सुमेलित कीजिए:\nA. बरार (इमादशाही) व बीदर (बरीदशाही)   |   1. मलिक अहमद\nB. अहमदनगर (निजामशाही, 1490)   |   2. कुली कुतुब शाह\nC. बीजापुर (आदिलशाही, 1489)   |   3. फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद\nD. गोलकुंडा (कुतुबशाही, 1512/18)   |   4. युसुफ आदिल शाह","options":["A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-2, D-4"],"correct":0,"explanation":"सही सुमेलन: बरार (इमादशाही) व बीदर (बरीदशाही) (फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद), अहमदनगर (निजामशाही, 1490) (मलिक अहमद), बीजापुर (आदिलशाही, 1489) (युसुफ आदिल शाह), गोलकुंडा (कुतुबशाही, 1512/18) (कुली कुतुब शाह)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. विजयनगर साम्राज्य में सती प्रथा पूर्णतः प्रतिबंधित थी तथा महिलाओं को सार्वजनिक उत्सवों या प्रशासन में भाग लेने की सख्त मनाही थी।\n2. मिहिर भोज गुर्जर-प्रतिहार वंश का सर्वाधिक प्रतापी शासक था जिसके समय अरब यात्री सुलेमान ने उसके साम्राज्य की सुदृढ़ कानून व्यवस्था की प्रशंसा की।\n3. जहाँगीर का काल मुगल चित्रकला का चरमोत्कर्ष ('स्वर्ण युग') था; वह चित्र देखकर प्रत्येक चित्रकार का नाम पहचानने का दावा करता था और उसने 'आगा रजा' के अधीन चित्रशाला खोली।\n4. हम्पी (तुंगभद्रा नदी के दक्षिण तट) को राजधानी बनाकर हरिहर एवं बुक्का ने दिल्ली सल्तनत से स्वतंत्र दक्षिण भारत का सबसे शक्तिशाली हिंदू साम्राज्य खड़ा किया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: विदेशी यात्रियों (कोंटी, पायस, नूनिज) के अनुसार विजयनगर में सती प्रथा व्यापक रूप से प्रचलित थी, यद्यपि महिलाएँ संगीत, नृत्य, लेखन व राजदरबारी कार्यों में दक्ष थीं।"},
  {"q":"[UPSC Prelims पैटर्न — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. फर्नओ नूनिज (पुर्तगाल) : अच्युतदेवराय (विजयनगर, ~1535 ई.)\n2. निकोलो कोंटी (इटली) : देवराय प्रथम (विजयनगर, 1420 ई.)\n3. अफनासी निकितिन (रूस) : बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (नूनिज ने अच्युतदेवराय के समय 3 वर्ष विजयनगर में रहकर महिलाओं के प्रशासनिक-सैन्य योगदान पर लिखा।) युग्म 2 सही (निकोलो कोंटी ने देवराय प्रथम के समय विजयनगर की यात्रा कर उत्सवों व सती प्रथा का वर्णन किया।) युग्म 3 सही (निकितिन ने बीदर केंद्रित बहमनी सल्तनत में आम जनता की गरीबी व अमीरों की विलासिता का वर्णन किया।)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: दक्कनी सल्तनत व राजवंश के अंतर्गत 'बीजापुर (आदिलशाही, 1489)' का ऐतिहासिक संबंध 'कुली कुतुब शाह' से था।\nकथन-2: शंकराचार्य के 'अद्वैतवाद' (केवल ब्रह्म सत्य, जगत मिथ्या) के विरुद्ध रामानुजाचार्य ने सगुण ईश्वर व भक्ति को मोक्ष का मार्ग बताते हुए 'विशिष्टाद्वैतवाद' दिया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('बीजापुर (आदिलशाही, 1489)' का सही संबंध 'युसुफ आदिल शाह' से था — युसुफ आदिल शाह ने 1489 में स्वतंत्र बीजापुर राज्य बनाया जहाँ बाद में गोल गुंबज बना।)। कथन-2 सत्य है (शंकराचार्य के 'अद्वैतवाद' (केवल ब्रह्म सत्य, जगत मिथ्या) के विरुद्ध रामानुजाचार्य ने सगुण ईश्वर व भक्ति को मोक्ष का मार्ग बताते हुए 'विशिष्टाद्वैतवाद' दिया।)।"},
  {"q":"फारसी राजदूत अब्दुर रज्जाक किस शासक के समय विजयनगर आए थे?","options":["अच्युतदेवराय (विजयनगर, ~1535 ई.)","कृष्णदेवराय (विजयनगर, ~1520 ई.)","देवराय द्वितीय (विजयनगर, 1443 ई.)","देवराय प्रथम (विजयनगर, 1420 ई.)"],"correct":2,"explanation":"शाहरुख के राजदूत अब्दुर रज्जाक ने देवराय II के समय हम्पी की अभेद्य सात दीवारों का वर्णन किया। उन्होंने कहा कि विश्व में विजयनगर जैसा भव्य नगर कभी देखा या सुना नहीं गया।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: विजयनगर साम्राज्य में सती प्रथा पूर्णतः प्रतिबंधित थी तथा महिलाओं को सार्वजनिक उत्सवों या प्रशासन में भाग लेने की सख्त मनाही थी।\nकथन-2: गयासुद्दीन तुगलक ने खिज्र खाँ को हराकर भारत में लोदी वंश की नींव डाली और सल्तनत में नहरों का निर्माण पूर्णतः बंद करा दिया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) विदेशी यात्रियों (कोंटी, पायस, नूनिज) के अनुसार विजयनगर में सती प्रथा व्यापक रूप से प्रचलित थी, यद्यपि महिलाएँ संगीत, नृत्य, लेखन व राजदरबारी कार्यों में दक्ष थीं। (2) गयासुद्दीन तुगलक ने खिलजी वंश के अंतिम शासक खुसरो खाँ को हराकर तुगलक वंश की नींव डाली और सल्तनत में नहर निर्माण की शुरुआत की।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. इब्नबतूता (मोरक्को) : मुहम्मद बिन तुगलक (1333 ई.)\n2. अब्दुर रज्जाक (फारस/समरकंद) : देवराय द्वितीय (विजयनगर, 1443 ई.)\n3. डोमिंगो पायस (पुर्तगाल) : अच्युतदेवराय (विजयनगर, ~1535 ई.)\n4. सर थॉमस रो (ब्रिटेन) : जहाँगीर (1615-1619 ई.)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'डोमिंगो पायस (पुर्तगाल)' का सही संबंध 'कृष्णदेवराय (विजयनगर, ~1520 ई.)' से है (न कि 'अच्युतदेवराय (विजयनगर, ~1535 ई.)' से)। डोमिंगो पायस ने तुलुव वंश के कृष्णदेवराय के व्यक्तित्व व महानवमी उत्सव का सुंदर चित्रण किया।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. उत्तर भारत के निर्गुण-सगुण संत: रामानंद, कबीर, नानक, शंकरदेव   B. किताब-ए-नवरस\nC. गुरु अमरदास (तीसरे गुरु)   D. बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["साम्राज्य, एवं","गुरु अमरदास (तीसरे गुरु)","उत्तर भारत के निर्गुण-सगुण संत: रामानंद, कबीर, नानक, शंकरदेव","किताब-ए-नवरस"],"correct":0,"explanation":"बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें (1347 ई.), उत्तर भारत के निर्गुण-सगुण संत: रामानंद, कबीर, नानक, शंकरदेव (1469 ई.), गुरु अमरदास (तीसरे गुरु) (1552-1574 ई.), किताब-ए-नवरस (1600 ई.)। अतः सर्वप्रथम बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: फारसी राजदूत अब्दुर रज्जाक तुगलक शासक फिरोजशाह के दरबार में दिल्ली आया था और उसने बहमनी की बजाय दिल्ली की सती प्रथा पर लिखा।\nकथन-2: मध्यकालीन ग्रंथ एवं लेखक के अंतर्गत 'हुमायूँनामा' का ऐतिहासिक संबंध 'मलिक मुहम्मद जायसी' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) अब्दुर रज्जाक (समरकंद/फारस के शाहरुख का दूत) 1443 में विजयनगर नरेश देवराय द्वितीय के दरबार में आया और हम्पी को विश्व के भव्यतम नगरों में गिना। (2) 'हुमायूँनामा' का सही संबंध 'गुलबदन बेगम' से था — बाबर की पुत्री व हुमायूँ की बहन गुलबदन बेगम ने अकबर के अनुरोध पर 'हुमायूँनामा' लिखा।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. गुरु हरगोबिंद (छठे गुरु)   B. बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें\nC. फर्नओ नूनिज (पुर्तगाल)   D. सर थॉमस रो (ब्रिटेन)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["साम्राज्य, एवं","फर्नओ नूनिज (पुर्तगाल)","गुरु हरगोबिंद (छठे गुरु)","सर थॉमस रो (ब्रिटेन)"],"correct":0,"explanation":"बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें (1347 ई.), फर्नओ नूनिज (पुर्तगाल) (1535 ई.), गुरु हरगोबिंद (छठे गुरु) (1606-1644 ई.), सर थॉमस रो (ब्रिटेन) (1615 ई.)। अतः सर्वप्रथम बहमनी साम्राज्य, महमूद गवां एवं पांच दक्कनी सल्तनतें।"},
  {"q":"[UPSC Prelims पैटर्न — दक्कनी सल्तनत व राजवंश] निम्नलिखित युग्मों पर विचार कीजिए:\n1. अहमदनगर (निजामशाही, 1490) : मलिक अहमद\n2. बीजापुर (आदिलशाही, 1489) : फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद\n3. बरार (इमादशाही) व बीदर (बरीदशाही) : कुली कुतुब शाह\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (मलिक अहमद ने 1490 में अहमदनगर की स्थापना की; यहीं वजीर मलिक अंबर ने छापामार युद्ध व राजस्व सुधार किए।) युग्म 2 गलत (सही: बीजापुर (आदिलशाही, 1489) — युसुफ आदिल शाह)। युग्म 3 गलत (सही: बरार (इमादशाही) व बीदर (बरीदशाही) — फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1565 ई. के तालीकोटा (राक्षसी-तंगड़ी या बन्नीहट्टी) युद्ध में दक्कनी सल्तनतों (बीजापुर, अहमदनगर, गोलकुंडा, बीदर) के महासंघ ने रामराय को हराकर विजयनगर की शक्ति तोड़ दी।\nकथन-2: सर-ए-नौबत मराठा सेना के संगठन, भर्ती व सैन्य अभियानों का शीर्ष सैन्य अधिकारी था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) 1565 ई. के तालीकोटा (राक्षसी-तंगड़ी या बन्नीहट्टी) युद्ध में दक्कनी सल्तनतों (बीजापुर, अहमदनगर, गोलकुंडा, बीदर) के महासंघ ने रामराय को हराकर विजयनगर की शक्ति तोड़ दी। (2) सर-ए-नौबत मराठा सेना के संगठन, भर्ती व सैन्य अभियानों का शीर्ष सैन्य अधिकारी था।"},
  {"q":"बहमनी सल्तनत के विघटन के बाद बीजापुर में 'आदिलशाही' वंश की स्थापना किसने की?","options":["मलिक अहमद","युसुफ आदिल शाह","कुली कुतुब शाह","फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद"],"correct":1,"explanation":"युसुफ आदिल शाह ने 1489 में स्वतंत्र बीजापुर राज्य बनाया जहाँ बाद में गोल गुंबज बना। 1686 ई. में औरंगजेब ने बीजापुर को मुगल साम्राज्य में मिलाया।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. फर्नओ नूनिज (पुर्तगाल) : अच्युतदेवराय (विजयनगर, ~1535 ई.)\n2. इब्नबतूता (मोरक्को) : मुहम्मद बिन तुगलक (1333 ई.)\n3. निकोलो कोंटी (इटली) : बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)\n4. अब्दुर रज्जाक (फारस/समरकंद) : देवराय द्वितीय (विजयनगर, 1443 ई.)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'निकोलो कोंटी (इटली)' का सही संबंध 'देवराय प्रथम (विजयनगर, 1420 ई.)' से है (न कि 'बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)' से)। निकोलो कोंटी ने देवराय प्रथम के समय विजयनगर की यात्रा कर उत्सवों व सती प्रथा का वर्णन किया।"},
  {"q":"[UPSC/PCS सूची सुमेलन — विदेशी यात्री एवं शासक] सूची-I को सूची-II से सुमेलित कीजिए:\nA. फर्नओ नूनिज (पुर्तगाल)   |   1. कृष्णदेवराय (विजयनगर, ~1520 ई.)\nB. डोमिंगो पायस (पुर्तगाल)   |   2. मुहम्मद बिन तुगलक (1333 ई.)\nC. फ्रांस्वा बर्नियर एवं टैवर्नियर   |   3. अच्युतदेवराय (विजयनगर, ~1535 ई.)\nD. इब्नबतूता (मोरक्को)   |   4. शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)","options":["A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-1, B-3, C-4, D-2"],"correct":1,"explanation":"सही सुमेलन: फर्नओ नूनिज (पुर्तगाल) (अच्युतदेवराय (विजयनगर, ~1535 ई.)), डोमिंगो पायस (पुर्तगाल) (कृष्णदेवराय (विजयनगर, ~1520 ई.)), फ्रांस्वा बर्नियर एवं टैवर्नियर (शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)), इब्नबतूता (मोरक्को) (मुहम्मद बिन तुगलक (1333 ई.))।"},
  {"q":"[UPSC Prelims पैटर्न — दक्कनी सल्तनत व राजवंश] निम्नलिखित युग्मों पर विचार कीजिए:\n1. अहमदनगर (निजामशाही, 1490) : मलिक अहमद\n2. बरार (इमादशाही) व बीदर (बरीदशाही) : फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद\n3. बीजापुर (आदिलशाही, 1489) : कुली कुतुब शाह\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (मलिक अहमद ने 1490 में अहमदनगर की स्थापना की; यहीं वजीर मलिक अंबर ने छापामार युद्ध व राजस्व सुधार किए।) युग्म 2 सही (बरार सबसे पहले 1484-90 में अलग हुआ व 1574 में अहमदनगर में विलीन हुआ; बीदर सबसे अंत में अलग हुआ।) युग्म 3 गलत (सही: बीजापुर (आदिलशाही, 1489) — युसुफ आदिल शाह)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: निकितिन ने बीदर केंद्रित बहमनी सल्तनत में आम जनता की गरीबी व अमीरों की विलासिता का वर्णन किया।\nकथन-2: अमीर खुसरो (1253-1325 ई., पटियाली में जन्म) निजामुद्दीन औलिया के प्रिय शिष्य थे जिन्होंने हिंदवी व फारसी संस्कृति के समन्वय ('गंगा-जमुनी तहजीब') की नींव रखी।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) निकितिन ने बीदर केंद्रित बहमनी सल्तनत में आम जनता की गरीबी व अमीरों की विलासिता का वर्णन किया। (2) अमीर खुसरो (1253-1325 ई., पटियाली में जन्म) निजामुद्दीन औलिया के प्रिय शिष्य थे जिन्होंने हिंदवी व फारसी संस्कृति के समन्वय ('गंगा-जमुनी तहजीब') की नींव रखी।"},
  {"q":"बहमनी से टूटकर बने 'बरार' में इमादशाही तथा 'बीदर' में बरीदशाही के संस्थापक क्रमशः कौन थे?","options":["कुली कुतुब शाह","मलिक अहमद","युसुफ आदिल शाह","फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद"],"correct":3,"explanation":"बरार सबसे पहले 1484-90 में अलग हुआ व 1574 में अहमदनगर में विलीन हुआ; बीदर सबसे अंत में अलग हुआ। इमादशाही की स्थापना फतुल्लाह इमाद शाह ने की और बरीदशाही की अली बरीद ने।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: विदेशी यात्री एवं शासक के अंतर्गत 'फर्नओ नूनिज (पुर्तगाल)' का ऐतिहासिक संबंध 'बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)' से था।\nकथन-2: सिख गुरु परंपरा के अंतर्गत 'गुरु हरगोबिंद (छठे गुरु)' का ऐतिहासिक संबंध 'धार्मिक स्वतंत्रता हेतु 1675 ई. में दिल्ली (शीशगंज) में शहादत' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'फर्नओ नूनिज (पुर्तगाल)' का सही संबंध 'अच्युतदेवराय (विजयनगर, ~1535 ई.)' से था — नूनिज ने अच्युतदेवराय के समय 3 वर्ष विजयनगर में रहकर महिलाओं के प्रशासनिक-सैन्य योगदान पर लिखा। (2) 'गुरु हरगोबिंद (छठे गुरु)' का सही संबंध 'अकाल तख्त की स्थापना व मीरी-पीरी दो तलवारें' से था — गुरु अर्जुन देव की शहादत के बाद छठे गुरु हरगोबिंद ने सिखों का सैन्यीकरण किया और अमृतसर की किलेबंदी की।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. विदेशी यात्री एवं शासक के अंतर्गत 'अब्दुर रज्जाक (फारस/समरकंद)' का ऐतिहासिक संबंध 'कृष्णदेवराय (विजयनगर, ~1520 ई.)' से था।\n2. पानीपत के द्वितीय युद्ध में अकबर के संरक्षक बैरम खाँ ने हिंदू सम्राट हेमू को पराजित किया।\n3. बहमनी सल्तनत के विघटन के बाद गोलकुंडा के कुतुबशाही सुल्तान मुहम्मद कुली कुतुब शाह ने हैदराबाद नगर तथा चारमीनार (1591) का निर्माण कराया।\n4. 1556 ई. में बैरम खाँ के संरक्षण में अकबर ने पानीपत के द्वितीय युद्ध में आदिल शाह सूर के हिंदू सेनापति हेमू ('विक्रमादित्य') को हराकर मुगल सत्ता पुनः स्थापित की।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: 'अब्दुर रज्जाक (फारस/समरकंद)' का सही संबंध 'देवराय द्वितीय (विजयनगर, 1443 ई.)' से था — शाहरुख के राजदूत अब्दुर रज्जाक ने देवराय II के समय हम्पी की अभेद्य सात दीवारों का वर्णन किया।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: बीजापुर के गोल गुंबज का निर्माण विजयनगर सम्राट रामराय ने महमूद गवां की स्मृति में कराया था।\nकथन-2: मुगलकालीन प्रमुख युद्ध के अंतर्गत 'हल्दीघाटी युद्ध (1576 ई.)' का ऐतिहासिक संबंध 'औरंगजेब व मुराद बनाम दारा शिकोह' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) बीजापुर के प्रसिद्ध गोल गुंबज (विश्व के सबसे बड़े एकल गुंबदों में से एक, व्हिस्परिंग गैलरी सहित) का निर्माण मुहम्मद आदिल शाह के मकबरे के रूप में हुआ। (2) 'हल्दीघाटी युद्ध (1576 ई.)' का सही संबंध 'महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)' से था — 18 जून 1576 को अरावली की हल्दीघाटी में मेवाड़ के महाराणा प्रताप ने अदम्य शौर्य दिखाया।"},
  {"q":"[PSC/CDS युग्म पहचान — विदेशी यात्री एवं शासक] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. डोमिंगो पायस (पुर्तगाल) : देवराय द्वितीय (विजयनगर, 1443 ई.)\n2. अब्दुर रज्जाक (फारस/समरकंद) : शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)\n3. निकोलो कोंटी (इटली) : देवराय प्रथम (विजयनगर, 1420 ई.)\n4. फ्रांस्वा बर्नियर एवं टैवर्नियर : जहाँगीर (1615-1619 ई.)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: निकोलो कोंटी ने देवराय प्रथम के समय विजयनगर की यात्रा कर उत्सवों व सती प्रथा का वर्णन किया। (अन्य सही युग्म: डोमिंगो पायस (पुर्तगाल)→कृष्णदेवराय (विजयनगर, ~1520 ई.), अब्दुर रज्जाक (फारस/समरकंद)→देवराय द्वितीय (विजयनगर, 1443 ई.), फ्रांस्वा बर्नियर एवं टैवर्नियर→शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68))।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. सल्तनत विभाग एवं सुल्तान के अंतर्गत 'दीवान-ए-विजारत' का ऐतिहासिक संबंध 'सैन्य विभाग (स्थापना: बलबन)' से था।\n2. मध्यकालीन स्थापत्य एवं निर्माता के अंतर्गत 'एत्मादुद्दौला का मकबरा (आगरा)' का ऐतिहासिक संबंध 'औरंगजेब (पुत्र आजम शाह द्वारा रबिया-उद-दुर्रानी हेतु)' से था।\n3. सूफी सिलसिले एवं शब्दावली के अंतर्गत 'सुहरावर्दी सिलसिला (भारत)' का ऐतिहासिक संबंध 'नक्शबंदी सिलसिला ('वहदत-उल-शुहूद' सिद्धांत)' से था।\n4. निकोलो कोंटी ने देवराय प्रथम के समय विजयनगर की यात्रा कर उत्सवों व सती प्रथा का वर्णन किया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (निकोलो कोंटी ने देवराय प्रथम के समय विजयनगर की यात्रा कर उत्सवों व सती प्रथा का वर्णन किया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[UPSC/PCS सूची सुमेलन — विदेशी यात्री एवं शासक] सूची-I को सूची-II से सुमेलित कीजिए:\nA. निकोलो कोंटी (इटली)   |   1. बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)\nB. फ्रांस्वा बर्नियर एवं टैवर्नियर   |   2. देवराय प्रथम (विजयनगर, 1420 ई.)\nC. अफनासी निकितिन (रूस)   |   3. मुहम्मद बिन तुगलक (1333 ई.)\nD. इब्नबतूता (मोरक्को)   |   4. शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)","options":["A-2, B-4, C-1, D-3","A-2, B-4, C-3, D-1","A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3"],"correct":0,"explanation":"सही सुमेलन: निकोलो कोंटी (इटली) (देवराय प्रथम (विजयनगर, 1420 ई.)), फ्रांस्वा बर्नियर एवं टैवर्नियर (शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)), अफनासी निकितिन (रूस) (बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)), इब्नबतूता (मोरक्को) (मुहम्मद बिन तुगलक (1333 ई.))।"},
  {"q":"[UPSC Prelims पैटर्न — दक्कनी सल्तनत व राजवंश] निम्नलिखित युग्मों पर विचार कीजिए:\n1. अहमदनगर (निजामशाही, 1490) : युसुफ आदिल शाह\n2. बीजापुर (आदिलशाही, 1489) : फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद\n3. बरार (इमादशाही) व बीदर (बरीदशाही) : कुली कुतुब शाह\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: अहमदनगर (निजामशाही, 1490) — मलिक अहमद)। युग्म 2 गलत (सही: बीजापुर (आदिलशाही, 1489) — युसुफ आदिल शाह)। युग्म 3 गलत (सही: बरार (इमादशाही) व बीदर (बरीदशाही) — फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद)।"},
  {"q":"[UPSC Prelims पैटर्न — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. फर्नओ नूनिज (पुर्तगाल) : कृष्णदेवराय (विजयनगर, ~1520 ई.)\n2. डोमिंगो पायस (पुर्तगाल) : देवराय प्रथम (विजयनगर, 1420 ई.)\n3. निकोलो कोंटी (इटली) : जहाँगीर (1615-1619 ई.)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: फर्नओ नूनिज (पुर्तगाल) — अच्युतदेवराय (विजयनगर, ~1535 ई.))। युग्म 2 गलत (सही: डोमिंगो पायस (पुर्तगाल) — कृष्णदेवराय (विजयनगर, ~1520 ई.))। युग्म 3 गलत (सही: निकोलो कोंटी (इटली) — देवराय प्रथम (विजयनगर, 1420 ई.))।"},
  {"q":"[UPSC Prelims पैटर्न — दक्कनी सल्तनत व राजवंश] निम्नलिखित युग्मों पर विचार कीजिए:\n1. बीजापुर (आदिलशाही, 1489) : युसुफ आदिल शाह\n2. बरार (इमादशाही) व बीदर (बरीदशाही) : फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद\n3. अहमदनगर (निजामशाही, 1490) : मलिक अहमद\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (युसुफ आदिल शाह ने 1489 में स्वतंत्र बीजापुर राज्य बनाया जहाँ बाद में गोल गुंबज बना।) युग्म 2 सही (बरार सबसे पहले 1484-90 में अलग हुआ व 1574 में अहमदनगर में विलीन हुआ; बीदर सबसे अंत में अलग हुआ।) युग्म 3 सही (मलिक अहमद ने 1490 में अहमदनगर की स्थापना की; यहीं वजीर मलिक अंबर ने छापामार युद्ध व राजस्व सुधार किए।)।"},
  {"q":"पुर्तगाली यात्री डोमिंगो पायस (Domingo Paes) ने किस सम्राट के काल में विजयनगर का विवरण लिखा?","options":["अच्युतदेवराय (विजयनगर, ~1535 ई.)","कृष्णदेवराय (विजयनगर, ~1520 ई.)","देवराय प्रथम (विजयनगर, 1420 ई.)","देवराय द्वितीय (विजयनगर, 1443 ई.)"],"correct":1,"explanation":"डोमिंगो पायस ने तुलुव वंश के कृष्णदेवराय के व्यक्तित्व व महानवमी उत्सव का सुंदर चित्रण किया। डुआर्टे बारबोसा भी कृष्णदेवराय के ही समय विजयनगर आए थे।"},
  {"q":"[UPSC/PCS सूची सुमेलन — दक्कनी सल्तनत व राजवंश] सूची-I को सूची-II से सुमेलित कीजिए:\nA. बीजापुर (आदिलशाही, 1489)   |   1. मलिक अहमद\nB. बरार (इमादशाही) व बीदर (बरीदशाही)   |   2. युसुफ आदिल शाह\nC. अहमदनगर (निजामशाही, 1490)   |   3. कुली कुतुब शाह\nD. गोलकुंडा (कुतुबशाही, 1512/18)   |   4. फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद","options":["A-2, B-4, C-1, D-3","A-2, B-4, C-3, D-1","A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3"],"correct":0,"explanation":"सही सुमेलन: बीजापुर (आदिलशाही, 1489) (युसुफ आदिल शाह), बरार (इमादशाही) व बीदर (बरीदशाही) (फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद), अहमदनगर (निजामशाही, 1490) (मलिक अहमद), गोलकुंडा (कुतुबशाही, 1512/18) (कुली कुतुब शाह)।"},
  {"q":"रूसी यात्री अफनासी निकितिन ने किस दक्षिण भारतीय राज्य की यात्रा की थी?","options":["देवराय प्रथम (विजयनगर, 1420 ई.)","बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)","कृष्णदेवराय (विजयनगर, ~1520 ई.)","देवराय द्वितीय (विजयनगर, 1443 ई.)"],"correct":1,"explanation":"निकितिन ने बीदर केंद्रित बहमनी सल्तनत में आम जनता की गरीबी व अमीरों की विलासिता का वर्णन किया। उनकी यात्रा का विवरण 'वोयेज बियॉन्ड थ्री सीज' में मिलता है।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. अलाई दरवाजा (1311 ई.)   B. अफनासी निकितिन (रूस)\nC. तबकात-ए-नासिरी   D. विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम","अलाई दरवाजा (1311 ई.)","(रूस)","तबकात-ए-नासिरी"],"correct":2,"explanation":"तबकात-ए-नासिरी (1260 ई.), अलाई दरवाजा (1311 ई.) (1311 ई.), विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम (1336 ई.), अफनासी निकितिन (रूस) (1470 ई.)। अतः सबसे अंत में अफनासी निकितिन (रूस)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: बीजापुर के गोल गुंबज का निर्माण विजयनगर सम्राट रामराय ने महमूद गवां की स्मृति में कराया था।\nकथन-2: मध्यकालीन स्थापत्य एवं निर्माता के अंतर्गत 'बीबी का मकबरा (औरंगाबाद)' का ऐतिहासिक संबंध 'इब्राहिम शाह शर्की ('पूर्व का सिराज')' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) बीजापुर के प्रसिद्ध गोल गुंबज (विश्व के सबसे बड़े एकल गुंबदों में से एक, व्हिस्परिंग गैलरी सहित) का निर्माण मुहम्मद आदिल शाह के मकबरे के रूप में हुआ। (2) 'बीबी का मकबरा (औरंगाबाद)' का सही संबंध 'औरंगजेब (पुत्र आजम शाह द्वारा रबिया-उद-दुर्रानी हेतु)' से था — औरंगजेब की पत्नी दिलरास बानो बेगम की स्मृति में 1651-61/78 के दौरान बीबी का मकबरा बना।"},
  {"q":"[UPSC Prelims PYQ] दिल्ली सल्तनत में किस सुल्तान ने कृषकों की सहायता हेतु 'दीवान-ए-कोही' की स्थापना कर अकालग्रस्त किसानों को 'सोंधर/तकावी' ऋण दिया?","options":["मुहम्मद बिन तुगलक","अलाउद्दीन खिलजी","सिकंदर लोदी","गयासुद्दीन तुगलक"],"correct":0,"explanation":"UPSC PYQ: मुहम्मद बिन तुगलक ने दोआब में कृषि विस्तार व फसल चक्र सुधार हेतु 'दीवान-ए-अमीर-ए-कोही' विभाग बनाया तथा सोंधर कृषि ऋण प्रदान किए।"},
  {"q":"[UPSC Prelims पैटर्न — दक्कनी सल्तनत व राजवंश] निम्नलिखित युग्मों पर विचार कीजिए:\n1. अहमदनगर (निजामशाही, 1490) : मलिक अहमद\n2. बीजापुर (आदिलशाही, 1489) : युसुफ आदिल शाह\n3. बरार (इमादशाही) व बीदर (बरीदशाही) : फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (मलिक अहमद ने 1490 में अहमदनगर की स्थापना की; यहीं वजीर मलिक अंबर ने छापामार युद्ध व राजस्व सुधार किए।) युग्म 2 सही (युसुफ आदिल शाह ने 1489 में स्वतंत्र बीजापुर राज्य बनाया जहाँ बाद में गोल गुंबज बना।) युग्म 3 सही (बरार सबसे पहले 1484-90 में अलग हुआ व 1574 में अहमदनगर में विलीन हुआ; बीदर सबसे अंत में अलग हुआ।)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. वाकियानवीस दरबारी घटनाक्रम दर्ज करने व गुप्तचर सूचनाओं को संकलित करने का कार्य करते थे।\n2. फिरोज तुगलक ने दासों के शिल्प प्रशिक्षण व देखभाल हेतु 'दीवान-ए-बंदगान' स्थापित किया।\n3. फारसी राजदूत अब्दुर रज्जाक तुगलक शासक फिरोजशाह के दरबार में दिल्ली आया था और उसने बहमनी की बजाय दिल्ली की सती प्रथा पर लिखा।\n4. 1739 में करनाल के युद्ध में नादिर शाह ने मुगल सेना को हराकर मयूर सिंहासन व कोहिनूर लूटा।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: अब्दुर रज्जाक (समरकंद/फारस के शाहरुख का दूत) 1443 में विजयनगर नरेश देवराय द्वितीय के दरबार में आया और हम्पी को विश्व के भव्यतम नगरों में गिना।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: शाहरुख के राजदूत अब्दुर रज्जाक ने देवराय II के समय हम्पी की अभेद्य सात दीवारों का वर्णन किया।\nकथन-2: सल्तनत विभाग एवं सुल्तान के अंतर्गत 'दीवान-ए-इंशा' का ऐतिहासिक संबंध 'धार्मिक मामले, वजीफे व राजनयिक/विदेश पत्राचार' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (शाहरुख के राजदूत अब्दुर रज्जाक ने देवराय II के समय हम्पी की अभेद्य सात दीवारों का वर्णन किया।)। कथन-2 गलत है — 'दीवान-ए-इंशा' का सही संबंध 'शाही पत्राचार, फरमान व अभिलेख विभाग' से था — दीवान-ए-इंशा सुल्तान के राजकीय फरमानों व प्रांतीय पत्राचार का प्रबंधन करता था।"},
  {"q":"[UPSC Prelims पैटर्न — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. अफनासी निकितिन (रूस) : बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)\n2. डोमिंगो पायस (पुर्तगाल) : कृष्णदेवराय (विजयनगर, ~1520 ई.)\n3. इब्नबतूता (मोरक्को) : मुहम्मद बिन तुगलक (1333 ई.)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (निकितिन ने बीदर केंद्रित बहमनी सल्तनत में आम जनता की गरीबी व अमीरों की विलासिता का वर्णन किया।) युग्म 2 सही (डोमिंगो पायस ने तुलुव वंश के कृष्णदेवराय के व्यक्तित्व व महानवमी उत्सव का सुंदर चित्रण किया।) युग्म 3 सही (मुहम्मद बिन तुगलक ने इब्नबतूता को दिल्ली का काजी नियुक्त किया और 1342 में चीन राजदूत भेजा।)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: बरार सबसे पहले 1484-90 में अलग हुआ व 1574 में अहमदनगर में विलीन हुआ; बीदर सबसे अंत में अलग हुआ।\nकथन-2: दक्कनी सल्तनत व राजवंश के अंतर्गत 'अहमदनगर (निजामशाही, 1490)' का ऐतिहासिक संबंध 'फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (बरार सबसे पहले 1484-90 में अलग हुआ व 1574 में अहमदनगर में विलीन हुआ; बीदर सबसे अंत में अलग हुआ।)। कथन-2 गलत है — 'अहमदनगर (निजामशाही, 1490)' का सही संबंध 'मलिक अहमद' से था — मलिक अहमद ने 1490 में अहमदनगर की स्थापना की; यहीं वजीर मलिक अंबर ने छापामार युद्ध व राजस्व सुधार किए।"},
  {"q":"[PSC/CDS युग्म पहचान — विदेशी यात्री एवं शासक] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. डोमिंगो पायस (पुर्तगाल) : कृष्णदेवराय (विजयनगर, ~1520 ई.)\n2. अफनासी निकितिन (रूस) : अच्युतदेवराय (विजयनगर, ~1535 ई.)\n3. फर्नओ नूनिज (पुर्तगाल) : देवराय द्वितीय (विजयनगर, 1443 ई.)\n4. अब्दुर रज्जाक (फारस/समरकंद) : शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: डोमिंगो पायस ने तुलुव वंश के कृष्णदेवराय के व्यक्तित्व व महानवमी उत्सव का सुंदर चित्रण किया। (अन्य सही युग्म: अफनासी निकितिन (रूस)→बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.), फर्नओ नूनिज (पुर्तगाल)→अच्युतदेवराय (विजयनगर, ~1535 ई.), अब्दुर रज्जाक (फारस/समरकंद)→देवराय द्वितीय (विजयनगर, 1443 ई.))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — दक्कनी सल्तनत व राजवंश] सूची-I को सूची-II से सुमेलित कीजिए:\nA. बरार (इमादशाही) व बीदर (बरीदशाही)   |   1. मलिक अहमद\nB. अहमदनगर (निजामशाही, 1490)   |   2. युसुफ आदिल शाह\nC. गोलकुंडा (कुतुबशाही, 1512/18)   |   3. फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद\nD. बीजापुर (आदिलशाही, 1489)   |   4. कुली कुतुब शाह","options":["A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2"],"correct":1,"explanation":"सही सुमेलन: बरार (इमादशाही) व बीदर (बरीदशाही) (फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद), अहमदनगर (निजामशाही, 1490) (मलिक अहमद), गोलकुंडा (कुतुबशाही, 1512/18) (कुली कुतुब शाह), बीजापुर (आदिलशाही, 1489) (युसुफ आदिल शाह)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: कुली कुतुब शाह ने गोलकुंडा राज्य की स्थापना की; बाद में मुहम्मद कुली कुतुब शाह ने चारमीनार बनवाई।\nकथन-2: मुगलकालीन प्रशासनिक शब्दावली के अंतर्गत 'हुण्डी' का ऐतिहासिक संबंध '1-2 वर्ष उर्वरता बढ़ाने हेतु खाली छोड़ी गई भूमि' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (कुली कुतुब शाह ने गोलकुंडा राज्य की स्थापना की; बाद में मुहम्मद कुली कुतुब शाह ने चारमीनार बनवाई।)। कथन-2 गलत है — 'हुण्डी' का सही संबंध 'व्यापारिक साख व विनिमय पत्र (Bill of Exchange)' से था — शराफों (बैंकरों) द्वारा जारी हुण्डी पर मुगल काल में दूर-दराज सुरक्षित भुगतान होता था (UPSC PYQ)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: विदेशी यात्री एवं शासक के अंतर्गत 'फर्नओ नूनिज (पुर्तगाल)' का ऐतिहासिक संबंध 'बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)' से था।\nकथन-2: मुगलकालीन प्रशासनिक शब्दावली के अंतर्गत 'परती (Parauti)' का ऐतिहासिक संबंध 'विद्वानों, संतों व धार्मिक संस्थानों को करमुक्त अनुदान भूमि' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'फर्नओ नूनिज (पुर्तगाल)' का सही संबंध 'अच्युतदेवराय (विजयनगर, ~1535 ई.)' से था — नूनिज ने अच्युतदेवराय के समय 3 वर्ष विजयनगर में रहकर महिलाओं के प्रशासनिक-सैन्य योगदान पर लिखा। (2) 'परती (Parauti)' का सही संबंध '1-2 वर्ष उर्वरता बढ़ाने हेतु खाली छोड़ी गई भूमि' से था — टोडरमल की दहसाला व्यवस्था में भूमि 4 वर्गों में थी: पोलज (प्रतिवर्ष खेती), परती, चाचर (3-4 वर्ष खाली), बंजर।"},
  {"q":"पुर्तगाली अश्व व्यापारी फर्नओ नूनिज (Fernao Nuniz) किस विजयनगर शासक के काल में आए?","options":["कृष्णदेवराय (विजयनगर, ~1520 ई.)","अच्युतदेवराय (विजयनगर, ~1535 ई.)","देवराय द्वितीय (विजयनगर, 1443 ई.)","देवराय प्रथम (विजयनगर, 1420 ई.)"],"correct":1,"explanation":"नूनिज ने अच्युतदेवराय के समय 3 वर्ष विजयनगर में रहकर महिलाओं के प्रशासनिक-सैन्य योगदान पर लिखा। नूनिज के अनुसार विजयनगर की कुछ महिलाएँ लेखाकार, ज्योतिषी, पहलवान व संगीतज्ञ थीं।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. गोलकुंडा (कुतुबशाही, 1512/18)   B. 18वीं सदी के स्वायत्त क्षेत्रीय राज्य: बंगाल, अवध व हैदराबाद\nC. बीबी का मकबरा (औरंगाबाद)   D. निकोलो कोंटी (इटली)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["18वीं सदी के स्वायत्त क्षेत्रीय राज्य: बंगाल, अवध व हैदराबाद","(इटली)","बीबी का मकबरा (औरंगाबाद)","गोलकुंडा (कुतुबशाही, 1512/18)"],"correct":1,"explanation":"निकोलो कोंटी (इटली) (1420 ई.), गोलकुंडा (कुतुबशाही, 1512/18) (1518 ई.), बीबी का मकबरा (औरंगाबाद) (1660 ई.), 18वीं सदी के स्वायत्त क्षेत्रीय राज्य: बंगाल, अवध व हैदराबाद (1724 ई.)। अतः सर्वप्रथम निकोलो कोंटी (इटली)।"},
  {"q":"ऐतिहासिक संदर्भ में 'तेलुगु में 'आमुक्तमाल्यद' व संस्कृत में 'जाम्बवती कल्याणम्'; दरबार में 8 तेलुगु कवि 'अष्टदिग्गज' (अल्लासानी पेड्डन्ना, तेनालीराम); 'आंध्र भोज' उपाधि' (साहित्य व सांस्कृतिक योगदान) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम","विजयनगर की कृषि, कर, मुद्रा एवं स्थानीय परंपराएँ","कृष्णदेवराय","अमर-नायक प्रणाली व विजयनगर आए विदेशी यात्री"],"correct":2,"explanation":"कृष्णदेवराय ने विवाह कर समाप्त कर सामाजिक सुधार किए तथा ओडिशा के गजपति शासक प्रतापरुद्र व बीजापुर के युसुफ आदिल शाह को पराजित किया। [तुलुव वंश]"},
  {"q":"गोलकुंडा (हैदराबाद) में प्रसिद्ध 'कुतुबशाही' वंश का संस्थापक कौन था?","options":["युसुफ आदिल शाह","फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद","मलिक अहमद","कुली कुतुब शाह"],"correct":3,"explanation":"कुली कुतुब शाह ने गोलकुंडा राज्य की स्थापना की; बाद में मुहम्मद कुली कुतुब शाह ने चारमीनार बनवाई। 1687 ई. में औरंगजेब ने गोलकुंडा का मुगल साम्राज्य में विलय किया।"},
  {"q":"[UPSC/PCS सूची सुमेलन — विदेशी यात्री एवं शासक] सूची-I को सूची-II से सुमेलित कीजिए:\nA. फर्नओ नूनिज (पुर्तगाल)   |   1. बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)\nB. फ्रांस्वा बर्नियर एवं टैवर्नियर   |   2. अच्युतदेवराय (विजयनगर, ~1535 ई.)\nC. अफनासी निकितिन (रूस)   |   3. देवराय द्वितीय (विजयनगर, 1443 ई.)\nD. अब्दुर रज्जाक (फारस/समरकंद)   |   4. शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)","options":["A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3"],"correct":1,"explanation":"सही सुमेलन: फर्नओ नूनिज (पुर्तगाल) (अच्युतदेवराय (विजयनगर, ~1535 ई.)), फ्रांस्वा बर्नियर एवं टैवर्नियर (शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)), अफनासी निकितिन (रूस) (बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)), अब्दुर रज्जाक (फारस/समरकंद) (देवराय द्वितीय (विजयनगर, 1443 ई.))।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1565 ई. के तालीकोटा (राक्षसी-तंगड़ी या बन्नीहट्टी) युद्ध में दक्कनी सल्तनतों (बीजापुर, अहमदनगर, गोलकुंडा, बीदर) के महासंघ ने रामराय को हराकर विजयनगर की शक्ति तोड़ दी।\nकथन-2: मध्यकालीन स्थापत्य एवं निर्माता के अंतर्गत 'सिकंदर लोदी का मकबरा (1517)' का ऐतिहासिक संबंध 'शेरशाह सूरी' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (1565 ई. के तालीकोटा (राक्षसी-तंगड़ी या बन्नीहट्टी) युद्ध में दक्कनी सल्तनतों (बीजापुर, अहमदनगर, गोलकुंडा, बीदर) के महासंघ ने रामराय को हराकर विजयनगर की शक्ति तोड़ दी।)। कथन-2 गलत है — 'सिकंदर लोदी का मकबरा (1517)' का सही संबंध 'भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)' से था — इब्राहिम लोदी द्वारा बनवाया गया सिकंदर लोदी का मकबरा मकबरों के 'उद्यान युग' की शुरुआत करता है।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: दक्कनी सल्तनत व राजवंश के अंतर्गत 'अहमदनगर (निजामशाही, 1490)' का ऐतिहासिक संबंध 'फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद' से था।\nकथन-2: मराठा अष्टप्रधान परिषद के अंतर्गत 'अमात्य (मजूमदार)' का ऐतिहासिक संबंध 'राजा के दैनिक कार्य, गृह व गुप्तचर मामलों का विवरण रखना' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'अहमदनगर (निजामशाही, 1490)' का सही संबंध 'मलिक अहमद' से था — मलिक अहमद ने 1490 में अहमदनगर की स्थापना की; यहीं वजीर मलिक अंबर ने छापामार युद्ध व राजस्व सुधार किए। (2) 'अमात्य (मजूमदार)' का सही संबंध 'वित्त एवं राजस्व लेखा-जोखा मंत्री' से था — अमात्य साम्राज्य के समस्त आय-व्यय का हिसाब रखते थे (आधुनिक वित्त मंत्री सदृश)।"},
  {"q":"[PSC/CDS युग्म पहचान — विदेशी यात्री एवं शासक] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. इब्नबतूता (मोरक्को) : कृष्णदेवराय (विजयनगर, ~1520 ई.)\n2. फर्नओ नूनिज (पुर्तगाल) : अच्युतदेवराय (विजयनगर, ~1535 ई.)\n3. डोमिंगो पायस (पुर्तगाल) : देवराय द्वितीय (विजयनगर, 1443 ई.)\n4. अब्दुर रज्जाक (फारस/समरकंद) : बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: नूनिज ने अच्युतदेवराय के समय 3 वर्ष विजयनगर में रहकर महिलाओं के प्रशासनिक-सैन्य योगदान पर लिखा। (अन्य सही युग्म: इब्नबतूता (मोरक्को)→मुहम्मद बिन तुगलक (1333 ई.), डोमिंगो पायस (पुर्तगाल)→कृष्णदेवराय (विजयनगर, ~1520 ई.), अब्दुर रज्जाक (फारस/समरकंद)→देवराय द्वितीय (विजयनगर, 1443 ई.))।"},
  {"q":"[UPSC Prelims पैटर्न — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. निकोलो कोंटी (इटली) : देवराय प्रथम (विजयनगर, 1420 ई.)\n2. अब्दुर रज्जाक (फारस/समरकंद) : देवराय द्वितीय (विजयनगर, 1443 ई.)\n3. इब्नबतूता (मोरक्को) : जहाँगीर (1615-1619 ई.)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (निकोलो कोंटी ने देवराय प्रथम के समय विजयनगर की यात्रा कर उत्सवों व सती प्रथा का वर्णन किया।) युग्म 2 सही (शाहरुख के राजदूत अब्दुर रज्जाक ने देवराय II के समय हम्पी की अभेद्य सात दीवारों का वर्णन किया।) युग्म 3 गलत (सही: इब्नबतूता (मोरक्को) — मुहम्मद बिन तुगलक (1333 ई.))।"},
  {"q":"[UPSC Prelims पैटर्न — दक्कनी सल्तनत व राजवंश] निम्नलिखित युग्मों पर विचार कीजिए:\n1. अहमदनगर (निजामशाही, 1490) : फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद\n2. बरार (इमादशाही) व बीदर (बरीदशाही) : युसुफ आदिल शाह\n3. बीजापुर (आदिलशाही, 1489) : कुली कुतुब शाह\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: अहमदनगर (निजामशाही, 1490) — मलिक अहमद)। युग्म 2 गलत (सही: बरार (इमादशाही) व बीदर (बरीदशाही) — फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद)। युग्म 3 गलत (सही: बीजापुर (आदिलशाही, 1489) — युसुफ आदिल शाह)।"},
  {"q":"[UPSC Prelims पैटर्न — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. अफनासी निकितिन (रूस) : देवराय द्वितीय (विजयनगर, 1443 ई.)\n2. अब्दुर रज्जाक (फारस/समरकंद) : मुहम्मद बिन तुगलक (1333 ई.)\n3. इब्नबतूता (मोरक्को) : कृष्णदेवराय (विजयनगर, ~1520 ई.)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: अफनासी निकितिन (रूस) — बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.))। युग्म 2 गलत (सही: अब्दुर रज्जाक (फारस/समरकंद) — देवराय द्वितीय (विजयनगर, 1443 ई.))। युग्म 3 गलत (सही: इब्नबतूता (मोरक्को) — मुहम्मद बिन तुगलक (1333 ई.))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — विदेशी यात्री एवं शासक] सूची-I को सूची-II से सुमेलित कीजिए:\nA. निकोलो कोंटी (इटली)   |   1. शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)\nB. डोमिंगो पायस (पुर्तगाल)   |   2. देवराय प्रथम (विजयनगर, 1420 ई.)\nC. फ्रांस्वा बर्नियर एवं टैवर्नियर   |   3. मुहम्मद बिन तुगलक (1333 ई.)\nD. इब्नबतूता (मोरक्को)   |   4. कृष्णदेवराय (विजयनगर, ~1520 ई.)","options":["A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3","A-2, B-4, C-3, D-1"],"correct":2,"explanation":"सही सुमेलन: निकोलो कोंटी (इटली) (देवराय प्रथम (विजयनगर, 1420 ई.)), डोमिंगो पायस (पुर्तगाल) (कृष्णदेवराय (विजयनगर, ~1520 ई.)), फ्रांस्वा बर्नियर एवं टैवर्नियर (शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)), इब्नबतूता (मोरक्को) (मुहम्मद बिन तुगलक (1333 ई.))।"},
  {"q":"ऐतिहासिक संदर्भ में '1347 ई. में अलाउद्दीन बहमन शाह (हसन गंगू) द्वारा स्थापना; 5 उत्तराधिकारी राज्य: बीजापुर (आदिलशाही), गोलकुंडा (कुतुबशाही), अहमदनगर (निजामशाही), बरार (इमादशाही), बीदर (बरीदशाही)' (बहमनी व पांच उत्तराधिकारी राज्य) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["ी साम् महमूद गवां एवं दक्कनी सल्तनतें","मिहिर भोज (गुर्जर-प्रतिहार), गोपाल व धर्मपाल (पाल)","चोल स्थानीय स्वशासन एवं उत्तरमेरूर अभिलेख","चोल सम्राट राजराज प्रथम एवं राजेंद्र प्रथम"],"correct":0,"explanation":"अहमदनगर की प्रसिद्ध रानी चाँद बीबी ने मुगल बादशाह अकबर की सेना के विरुद्ध वीरतापूर्वक अपने राज्य की रक्षा की थी।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: बहमनी सल्तनत के विघटन के बाद गोलकुंडा के कुतुबशाही सुल्तान मुहम्मद कुली कुतुब शाह ने हैदराबाद नगर तथा चारमीनार (1591) का निर्माण कराया।\nकथन-2: ऐतिहासिक युद्ध एवं परिणाम के अंतर्गत 'चौसा का युद्ध (1539 ई.)' का ऐतिहासिक संबंध 'अकबर-बैरम खाँ ने आदिल शाह के सेनापति हेमू (विक्रमादित्य) को हराया' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (बहमनी सल्तनत के विघटन के बाद गोलकुंडा के कुतुबशाही सुल्तान मुहम्मद कुली कुतुब शाह ने हैदराबाद नगर तथा चारमीनार (1591) का निर्माण कराया।)। कथन-2 गलत है — 'चौसा का युद्ध (1539 ई.)' का सही संबंध 'शेर खान (शेरशाह सूरी) ने हुमायूँ को पराजित कर 'शेरशाह' उपाधि धारण की' से था — 1539 ई. में बक्सर के निकट चौसा के युद्ध में शेरशाह सूरी ने हुमायूँ को पराजित किया।"},
  {"q":"[UPSC Prelims पैटर्न — दक्कनी सल्तनत व राजवंश] निम्नलिखित युग्मों पर विचार कीजिए:\n1. अहमदनगर (निजामशाही, 1490) : मलिक अहमद\n2. बरार (इमादशाही) व बीदर (बरीदशाही) : युसुफ आदिल शाह\n3. बीजापुर (आदिलशाही, 1489) : कुली कुतुब शाह\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (मलिक अहमद ने 1490 में अहमदनगर की स्थापना की; यहीं वजीर मलिक अंबर ने छापामार युद्ध व राजस्व सुधार किए।) युग्म 2 गलत (सही: बरार (इमादशाही) व बीदर (बरीदशाही) — फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद)। युग्म 3 गलत (सही: बीजापुर (आदिलशाही, 1489) — युसुफ आदिल शाह)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: विदेशी यात्री एवं शासक के अंतर्गत 'डोमिंगो पायस (पुर्तगाल)' का ऐतिहासिक संबंध 'अच्युतदेवराय (विजयनगर, ~1535 ई.)' से था।\nकथन-2: विजयनगर साम्राज्य में सती प्रथा पूर्णतः प्रतिबंधित थी तथा महिलाओं को सार्वजनिक उत्सवों या प्रशासन में भाग लेने की सख्त मनाही थी।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'डोमिंगो पायस (पुर्तगाल)' का सही संबंध 'कृष्णदेवराय (विजयनगर, ~1520 ई.)' से था — डोमिंगो पायस ने तुलुव वंश के कृष्णदेवराय के व्यक्तित्व व महानवमी उत्सव का सुंदर चित्रण किया। (2) विदेशी यात्रियों (कोंटी, पायस, नूनिज) के अनुसार विजयनगर में सती प्रथा व्यापक रूप से प्रचलित थी, यद्यपि महिलाएँ संगीत, नृत्य, लेखन व राजदरबारी कार्यों में दक्ष थीं।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. 18वीं सदी के स्वायत्त क्षेत्रीय राज्य: बंगाल, अवध व हैदराबाद   B. उत्तर-मुगल शासक, सैय्यद बंधु एवं नादिर शाह का आक्रमण\nC. अहमदनगर (निजामशाही, 1490)   D. पानीपत का तृतीय युद्ध (1761 ई.)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["उत्तर-मुगल शासक, सैय्यद बंधु एवं नादिर शाह का आक्रमण","18वीं सदी के स्वायत्त क्षेत्रीय राज्य: बंगाल, अवध व हैदराबाद","( )","पानीपत का तृतीय युद्ध (1761 ई.)"],"correct":2,"explanation":"अहमदनगर (निजामशाही, 1490) (1490 ई.), 18वीं सदी के स्वायत्त क्षेत्रीय राज्य: बंगाल, अवध व हैदराबाद (1724 ई.), उत्तर-मुगल शासक, सैय्यद बंधु एवं नादिर शाह का आक्रमण (1739 ई.), पानीपत का तृतीय युद्ध (1761 ई.) (1761 ई.)। अतः सर्वप्रथम अहमदनगर (निजामशाही, 1490)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: विदेशी यात्री एवं शासक के अंतर्गत 'अफनासी निकितिन (रूस)' का ऐतिहासिक संबंध 'मुहम्मद बिन तुगलक (1333 ई.)' से था।\nकथन-2: 1675 ई. में औरंगजेब के जबरन धर्मांतरण के विरोध पर दिल्ली के चाँदनी चौक में गुरु तेग बहादुर ने बलिदान दिया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('अफनासी निकितिन (रूस)' का सही संबंध 'बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)' से था — निकितिन ने बीदर केंद्रित बहमनी सल्तनत में आम जनता की गरीबी व अमीरों की विलासिता का वर्णन किया।)। कथन-2 सत्य है (1675 ई. में औरंगजेब के जबरन धर्मांतरण के विरोध पर दिल्ली के चाँदनी चौक में गुरु तेग बहादुर ने बलिदान दिया।)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. अकबर ने जजिया कर अपने शासन के अंतिम वर्ष 1601 ई. में असीरगढ़ विजय के बाद पहली बार लगाया था।\n2. दक्कनी सल्तनत व राजवंश के अंतर्गत 'अहमदनगर (निजामशाही, 1490)' का ऐतिहासिक संबंध 'फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद' से था।\n3. सूफी सिलसिले एवं शब्दावली के अंतर्गत 'शेख अहमद सरहिन्दी' का ऐतिहासिक संबंध 'शेख बहाउद्दीन जकरिया (मुल्तान)' से था।\n4. बहमनी सल्तनत के विघटन के बाद गोलकुंडा के कुतुबशाही सुल्तान मुहम्मद कुली कुतुब शाह ने हैदराबाद नगर तथा चारमीनार (1591) का निर्माण कराया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (बहमनी सल्तनत के विघटन के बाद गोलकुंडा के कुतुबशाही सुल्तान मुहम्मद कुली कुतुब शाह ने हैदराबाद नगर तथा चारमीनार (1591) का निर्माण कराया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: युसुफ आदिल शाह ने 1489 में स्वतंत्र बीजापुर राज्य बनाया जहाँ बाद में गोल गुंबज बना।\nकथन-2: विजयनगर साम्राज्य में सती प्रथा पूर्णतः प्रतिबंधित थी तथा महिलाओं को सार्वजनिक उत्सवों या प्रशासन में भाग लेने की सख्त मनाही थी।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (युसुफ आदिल शाह ने 1489 में स्वतंत्र बीजापुर राज्य बनाया जहाँ बाद में गोल गुंबज बना।)। कथन-2 गलत है — विदेशी यात्रियों (कोंटी, पायस, नूनिज) के अनुसार विजयनगर में सती प्रथा व्यापक रूप से प्रचलित थी, यद्यपि महिलाएँ संगीत, नृत्य, लेखन व राजदरबारी कार्यों में दक्ष थीं।"},
  {"q":"[UPSC Prelims पैटर्न — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. अब्दुर रज्जाक (फारस/समरकंद) : देवराय द्वितीय (विजयनगर, 1443 ई.)\n2. निकोलो कोंटी (इटली) : देवराय प्रथम (विजयनगर, 1420 ई.)\n3. फ्रांस्वा बर्नियर एवं टैवर्नियर : बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (शाहरुख के राजदूत अब्दुर रज्जाक ने देवराय II के समय हम्पी की अभेद्य सात दीवारों का वर्णन किया।) युग्म 2 सही (निकोलो कोंटी ने देवराय प्रथम के समय विजयनगर की यात्रा कर उत्सवों व सती प्रथा का वर्णन किया।) युग्म 3 गलत (सही: फ्रांस्वा बर्नियर एवं टैवर्नियर — शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68))।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: कृष्णदेवराय के दरबार के प्रसिद्ध 'अष्टदिग्गज' संस्कृत के आठ वैदिक कर्मकांडी मंत्रियों की प्रशासनिक परिषद थी।\nकथन-2: 1191 ई. में तराइन के प्रथम युद्ध में पृथ्वीराज चौहान ने मुहम्मद गौरी को पराजित किया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है (विजयनगर के 'अष्टदिग्गज' आठ महान तेलुगु साहित्यकार/कवि थे (जबकि शिवाजी की प्रशासनिक मंत्री परिषद 'अष्टप्रधान' कहलाती थी)।)। कथन-2 सत्य है (1191 ई. में तराइन के प्रथम युद्ध में पृथ्वीराज चौहान ने मुहम्मद गौरी को पराजित किया।)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — विदेशी यात्री एवं शासक] सूची-I को सूची-II से सुमेलित कीजिए:\nA. अब्दुर रज्जाक (फारस/समरकंद)   |   1. कृष्णदेवराय (विजयनगर, ~1520 ई.)\nB. इब्नबतूता (मोरक्को)   |   2. शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)\nC. फ्रांस्वा बर्नियर एवं टैवर्नियर   |   3. देवराय द्वितीय (विजयनगर, 1443 ई.)\nD. डोमिंगो पायस (पुर्तगाल)   |   4. मुहम्मद बिन तुगलक (1333 ई.)","options":["A-3, B-4, C-1, D-2","A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1"],"correct":2,"explanation":"सही सुमेलन: अब्दुर रज्जाक (फारस/समरकंद) (देवराय द्वितीय (विजयनगर, 1443 ई.)), इब्नबतूता (मोरक्को) (मुहम्मद बिन तुगलक (1333 ई.)), फ्रांस्वा बर्नियर एवं टैवर्नियर (शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)), डोमिंगो पायस (पुर्तगाल) (कृष्णदेवराय (विजयनगर, ~1520 ई.))।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. फ्रांस्वा बर्नियर एवं टैवर्नियर : शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)\n2. सर थॉमस रो (ब्रिटेन) : जहाँगीर (1615-1619 ई.)\n3. अफनासी निकितिन (रूस) : देवराय प्रथम (विजयनगर, 1420 ई.)\n4. अब्दुर रज्जाक (फारस/समरकंद) : देवराय द्वितीय (विजयनगर, 1443 ई.)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'अफनासी निकितिन (रूस)' का सही संबंध 'बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)' से है (न कि 'देवराय प्रथम (विजयनगर, 1420 ई.)' से)। निकितिन ने बीदर केंद्रित बहमनी सल्तनत में आम जनता की गरीबी व अमीरों की विलासिता का वर्णन किया।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. अब्दुर रज्जाक (फारस/समरकंद) : कृष्णदेवराय (विजयनगर, ~1520 ई.)\n2. अफनासी निकितिन (रूस) : बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)\n3. फर्नओ नूनिज (पुर्तगाल) : अच्युतदेवराय (विजयनगर, ~1535 ई.)\n4. निकोलो कोंटी (इटली) : देवराय प्रथम (विजयनगर, 1420 ई.)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'अब्दुर रज्जाक (फारस/समरकंद)' का सही संबंध 'देवराय द्वितीय (विजयनगर, 1443 ई.)' से है (न कि 'कृष्णदेवराय (विजयनगर, ~1520 ई.)' से)। शाहरुख के राजदूत अब्दुर रज्जाक ने देवराय II के समय हम्पी की अभेद्य सात दीवारों का वर्णन किया।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. वल्लभाचार्य ने बिना संन्यास लिए गृहस्थ जीवन में कृष्ण के बाल रूप की भक्ति ('पुष्टिमार्ग') का उपदेश दिया।\n2. इब्राहिम लोदी द्वारा बनवाया गया सिकंदर लोदी का मकबरा मकबरों के 'उद्यान युग' की शुरुआत करता है।\n3. दक्कनी सल्तनत व राजवंश के अंतर्गत 'बीजापुर (आदिलशाही, 1489)' का ऐतिहासिक संबंध 'कुली कुतुब शाह' से था।\n4. 1674 ई. में रायगढ़ किले में काशी के पंडित विश्वेश्वर (गंगाभट्ट) ने शिवाजी का राज्याभिषेक किया और उन्होंने 'छत्रपति', 'हैंदव धर्मोद्धारक' व 'गोब्राह्मण प्रतिपालक' उपाधि ली।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: 'बीजापुर (आदिलशाही, 1489)' का सही संबंध 'युसुफ आदिल शाह' से था — युसुफ आदिल शाह ने 1489 में स्वतंत्र बीजापुर राज्य बनाया जहाँ बाद में गोल गुंबज बना।"},
  {"q":"ऐतिहासिक संदर्भ में 'निकोलो कोंटी (इटली — देवराय I), अब्दुर रज्जाक (फारस — देवराय II), बारबोसा व डोमिंगो पायस (कृष्णदेवराय), नूनिज (अच्युतदेवराय), निकितिन (बहमनी)' (प्रमुख विदेशी यात्री) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["कृष्णदेवराय (तुलुव वंश) एवं अष्टदिग्गज","विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम","विजयनगर की कृषि, कर, मुद्रा एवं स्थानीय परंपराएँ","अमर-नायक प्रणाली व विजयनगर आए"],"correct":3,"explanation":"पुर्तगाली यात्री नूनिज ने विजयनगर साम्राज्य में महिलाओं को कुश्ती, ज्योतिष, लेखा-जोखा व राजमहल की अंगरक्षिका के रूप में कार्यरत देखा (UPSC PYQ)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. पानीपत का तृतीय युद्ध (1761 ई.)   B. अफनासी निकितिन (रूस)\nC. अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान   D. बीजापुर (आदिलशाही, 1489)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["पानीपत का तृतीय युद्ध (1761 ई.)","(रूस)","अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान","बीजापुर (आदिलशाही, 1489)"],"correct":1,"explanation":"अफनासी निकितिन (रूस) (1470 ई.), बीजापुर (आदिलशाही, 1489) (1489 ई.), अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान (1556-1605 ई.), पानीपत का तृतीय युद्ध (1761 ई.) (1761 ई.)। अतः सर्वप्रथम अफनासी निकितिन (रूस)।"},
  {"q":"[UPSC Prelims पैटर्न — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. अफनासी निकितिन (रूस) : बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)\n2. डोमिंगो पायस (पुर्तगाल) : कृष्णदेवराय (विजयनगर, ~1520 ई.)\n3. इब्नबतूता (मोरक्को) : शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (निकितिन ने बीदर केंद्रित बहमनी सल्तनत में आम जनता की गरीबी व अमीरों की विलासिता का वर्णन किया।) युग्म 2 सही (डोमिंगो पायस ने तुलुव वंश के कृष्णदेवराय के व्यक्तित्व व महानवमी उत्सव का सुंदर चित्रण किया।) युग्म 3 गलत (सही: इब्नबतूता (मोरक्को) — मुहम्मद बिन तुगलक (1333 ई.))।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. पद्मावत (अवधी, 1540)   B. पुरंदर की संधि (1665 ई.)\nC. अहमदनगर (निजामशाही, 1490)   D. निकोलो कोंटी (इटली)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["पद्मावत (अवधी, 1540)","पुरंदर की संधि (1665 ई.)","(इटली)","अहमदनगर (निजामशाही, 1490)"],"correct":2,"explanation":"निकोलो कोंटी (इटली) (1420 ई.), अहमदनगर (निजामशाही, 1490) (1490 ई.), पद्मावत (अवधी, 1540) (1540 ई.), पुरंदर की संधि (1665 ई.) (1665 ई.)। अतः सर्वप्रथम निकोलो कोंटी (इटली)।"},
  {"q":"[UPSC Prelims पैटर्न — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. निकोलो कोंटी (इटली) : देवराय प्रथम (विजयनगर, 1420 ई.)\n2. इब्नबतूता (मोरक्को) : मुहम्मद बिन तुगलक (1333 ई.)\n3. अब्दुर रज्जाक (फारस/समरकंद) : देवराय द्वितीय (विजयनगर, 1443 ई.)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (निकोलो कोंटी ने देवराय प्रथम के समय विजयनगर की यात्रा कर उत्सवों व सती प्रथा का वर्णन किया।) युग्म 2 सही (मुहम्मद बिन तुगलक ने इब्नबतूता को दिल्ली का काजी नियुक्त किया और 1342 में चीन राजदूत भेजा।) युग्म 3 सही (शाहरुख के राजदूत अब्दुर रज्जाक ने देवराय II के समय हम्पी की अभेद्य सात दीवारों का वर्णन किया।)।"},
  {"q":"ऐतिहासिक संदर्भ में '1336 ई. में हरिहर I व बुक्का I (गुरु विद्यारण्य की प्रेरणा) द्वारा स्थापना; 4 वंश क्रम: संगम -> सालुव -> तुलुव -> अराविदु' (चार राजवंश व स्थापना) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["विजयनगर साम्राज्य की एवं","कृष्णदेवराय (तुलुव वंश) एवं अष्टदिग्गज","अमर-नायक प्रणाली व विजयनगर आए विदेशी यात्री","विजयनगर की कृषि, कर, मुद्रा एवं स्थानीय परंपराएँ"],"correct":0,"explanation":"बुक्का प्रथम की पुत्रवधू गंगादेवी ने अपने पति कुमार कंपण के मदुरै विजय अभियान पर संस्कृत महाकाव्य 'मदुराविजयम्' की रचना की।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: विजयनगर साम्राज्य पर शासन करने वाले चार राजवंशों का सही कालानुक्रम तुलुव -> संगम -> सालुव -> अराविदु था।\nकथन-2: शिवाजी ने अपनी स्वराज भूमि में 'मोकसा' (जागीर) प्रथा समाप्त कर 'कथियारी' (भू-माप) पर सीधी वसूली लागू की तथा कान्होजी आंग्रे जैसे नौसेना नायकों ने यूरोपीय जहाजों को चुनौती दी।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है (विजयनगर पर राजवंशों का सही कालानुक्रम संगम (1336-1485) -> सालुव (1485-1505) -> तुलुव (1505-1570) -> अराविदु (1570-1650) था।)। कथन-2 सत्य है (शिवाजी ने अपनी स्वराज भूमि में 'मोकसा' (जागीर) प्रथा समाप्त कर 'कथियारी' (भू-माप) पर सीधी वसूली लागू की तथा कान्होजी आंग्रे जैसे नौसेना नायकों ने यूरोपीय जहाजों को चुनौती दी।)।"},
  {"q":"इतालवी यात्री निकोलो कोंटी किस विजयनगर शासक के काल में भारत आया था?","options":["देवराय द्वितीय (विजयनगर, 1443 ई.)","कृष्णदेवराय (विजयनगर, ~1520 ई.)","अच्युतदेवराय (विजयनगर, ~1535 ई.)","देवराय प्रथम (विजयनगर, 1420 ई.)"],"correct":3,"explanation":"निकोलो कोंटी ने देवराय प्रथम के समय विजयनगर की यात्रा कर उत्सवों व सती प्रथा का वर्णन किया। उन्होंने विजयनगर शहर की परिधि लगभग 60 मील आंकी थी।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. सिखों के दस गुरु एवं खालसा पंथ की स्थापना (1699)   B. किताब-ए-नवरस\nC. निकोलो कोंटी (इटली)   D. बरार (इमादशाही) व बीदर (बरीदशाही)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["(इटली)","किताब-ए-नवरस","सिखों के दस गुरु एवं खालसा पंथ की स्थापना (1699)","बरार (इमादशाही) व बीदर (बरीदशाही)"],"correct":0,"explanation":"निकोलो कोंटी (इटली) (1420 ई.), बरार (इमादशाही) व बीदर (बरीदशाही) (1490 ई.), किताब-ए-नवरस (1600 ई.), सिखों के दस गुरु एवं खालसा पंथ की स्थापना (1699) (1699 ई.)। अतः सर्वप्रथम निकोलो कोंटी (इटली)।"}
]);
